-- ─── BAND 5 · KORSTOG (4 questions) ──────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Opfyldte korstogene kriterierne for en retfærdig krig (jus ad bellum) — og hvad viser en etisk analyse om afstanden mellem ideologi og faktisk praksis?","options":["Korstogene opfyldte formelt dele af jus ad bellum-kriterierne (retfærdig sag, legitim autoritet via pavelig proklamation, ret intention). Men praksis afveg systematisk: massakren i Jerusalem 1099, Konstantinopels plyndring i 4. korstog 1204 og forfølgelse af europæiske jøder underminerede etisk legitimation. Ideologisk begrundelse og faktisk adfærd var konsistent adskilt — de religiøse rammer muliggjorde handlinger der ellers var moralsk utænkelige","Korstogene opfyldte fuldt og uproblematisk alle kriterier for retfærdig krig og er etisk uproblematiske i historisk kontekst","Korstogene var ren aggressiv ekspansion og begrebet retfærdig krig er totalt irrelevant som analytisk ramme for perioden","Just war-teorien opstod først med Hugo Grotius i 1600-tallet og er anakronistisk at anvende på korstogene i det hele taget"],"correct":"Korstogene opfyldte formelt dele af jus ad bellum-kriterierne (retfærdig sag, legitim autoritet via pavelig proklamation, ret intention). Men praksis afveg systematisk: massakren i Jerusalem 1099, Konstantinopels plyndring i 4. korstog 1204 og forfølgelse af europæiske jøder underminerede etisk legitimation. Ideologisk begrundelse og faktisk adfærd var konsistent adskilt — de religiøse rammer muliggjorde handlinger der ellers var moralsk utænkelige","accepted_answers":["Korstogene opfyldte formelt dele af jus ad bellum-kriterierne (retfærdig sag, legitim autoritet via pavelig proklamation, ret intention). Men praksis afveg systematisk: massakren i Jerusalem 1099, Konstantinopels plyndring i 4. korstog 1204 og forfølgelse af europæiske jøder underminerede etisk legitimation. Ideologisk begrundelse og faktisk adfærd var konsistent adskilt — de religiøse rammer muliggjorde handlinger der ellers var moralsk utænkelige"],"review_text":"Thomas Aquinas (Summa Theologiae, 1265-74) systematiserede den augustinske jus ad bellum-tradition: retfærdig krig kræver retfærdig sag, legitim autoritet, ret intention, krig som sidste udvej og rimelig chance for succes. Pave Urban IIs Clermont-tale (1095) opfyldte formelt disse krav: befrielse af Det Hellige Land og forsvar for østkirkens kristne mod seljukkisk ekspansion. Men jus in bello (krigsadfærd) brød konsistent med rammen. Korsfarernes massakre i Jerusalem 1099 dræbte anslagsvis 30.000-40.000 muslimer og jøder. 4. korstogs plyndring af Konstantinopel 1204 ramte et kristent samfund. Jonathan Riley-Smiths The Crusades (2005) og Thomas Asbridge dokumenterer at korsfarerne selv var bevidste om spændingen — men institutionelle og gruppedynamiske mekanismer muliggjorde handlinger der individuelt var moralsk uacceptable. Hannah Arendts analyse af autoritetslydighed og kollektiv ansvarsfraskrivelse er metodologisk relevant: religiøse rammer suspenderede individuelle moralske evalueringer præcis som bureaukratiske rammer kan."}$$::jsonb,
  'mc','short',$${"concepts":["jus ad bellum","korstog","Jerusalem 1099","4. korstog","Riley-Smith","etisk analyse"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var korstogene primært religiøst motiverede — eller er den religiøse fortolkning et dække for politiske og materielle interesser?","options":["Multi-kausal analyse er nødvendig: religiøs motivation var reel og dokumenteret (frelsestrang, pilegrimstradition, pavens spirituelle autoritet mobiliserede ægte overbevisning) men sameksisterede med materielle og politiske faktorer (adelens yngre sønners arveproblemer, handelsmæssige interesser i Levanten). Riley-Smiths kildestudier viser at mange korsfarere faktisk led ekonomiske tab ved deltagelse — rene opportunister ville ikke have deltaget","Korstogene var udelukkende religiøse og alle materielle og politiske forklaringer er moderne anakronistiske reduktionismer der ignorerer periodens selvforståelse","Korstogene var udelukkende politisk og ekonomisk motiverede og religion var kun et manipulerende retorisk dække uden reel motiverende kraft for deltagerne","Korstogstilslutning forklares udelukkende af sociale og gruppedynamiske pres uden hensyn til individuelle motivationer og overbevisninger"],"correct":"Multi-kausal analyse er nødvendig: religiøs motivation var reel og dokumenteret (frelsestrang, pilegrimstradition, pavens spirituelle autoritet mobiliserede ægte overbevisning) men sameksisterede med materielle og politiske faktorer (adelens yngre sønners arveproblemer, handelsmæssige interesser i Levanten). Riley-Smiths kildestudier viser at mange korsfarere faktisk led ekonomiske tab ved deltagelse — rene opportunister ville ikke have deltaget","accepted_answers":["Multi-kausal analyse er nødvendig: religiøs motivation var reel og dokumenteret (frelsestrang, pilegrimstradition, pavens spirituelle autoritet mobiliserede ægte overbevisning) men sameksisterede med materielle og politiske faktorer (adelens yngre sønners arveproblemer, handelsmæssige interesser i Levanten). Riley-Smiths kildestudier viser at mange korsfarere faktisk led ekonomiske tab ved deltagelse — rene opportunister ville ikke have deltaget"],"review_text":"Motivationsdebatten i korstogshistoriografien har tre hovedpositioner. Den ældre religiøse fortolkning (Runciman) betonede kristen fromhed og pilgrimsideologi. Den materialistiske revisionisme (Smail, Prawer) fokuserede på feudaladlens ekspansionsdrift, handelsinteresser og den demografiske pres fra en overproducerende krigerklasse. Riley-Smiths What Were the Crusades? (1977, revideret 2009) introducerede det metodologisk vigtigste argument: kildestudier viser at korsfarernes udgifter systematisk oversteg det ekonomisk rationelle. Mange mellemstore adelige pantsatte godser og optog gæld for at finansiere korstogsfærden — en adfærd der er inkonsistent med ren opportunisme. Det betyder ikke at materielle motiver var fraværende men at religiøs motivation ikke kan reduceres væk. Benjamin Kedar (Crusade and Mission, 1984) viser at korsfarernes selvforståelse var genuint religiøs selv når vi kan identificere sammenfaldende materielle interesser. Multi-kausalitet er ikke en metodisk flugt men den empirisk mest forsvarlige position."}$$::jsonb,
  'mc','short',$${"concepts":["korstogsmotivation","religiøs vs materiel","Riley-Smith","kildekritik","multi-kausalitet","Runciman"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvilke fundamentalt forskellige historiske narrativer eksisterer om korstogene — og hvad afslører den historiografiske divergens om historiens konstruktion?","options":["Europæisk narrativ (dominerende frem til nyere tid): heroisk kristent forsvar og civilisationsprojekt. Islamisk narrativ: destruktiv invasion der aktiveres i kollektiv hukommelse som forløber for kolonialisme. Divergensen viser at historisk meningsdannelse er nutidsbestemt: korstogene blev centralt meningsbærende i arabisk politisk diskurs under europæisk imperialisme og Israel-Palæstina-konflikten — ikke som neutral historisk erindring men som politisk ressource","Der eksisterer kun ét historiografisk korrekt narrativ om korstogene og den islamiske forståelse er et politisk konstrueret narrativ uden historisk legitimitet","Alle historiske narrativer om korstogene er principielt lige gyldige og der er ingen mulig analytisk vurdering eller hierarkisering af dem","Korstogene fylder for lidt i moderne forskning til at der er meningsfulde historiografiske divergenser at diskutere"],"correct":"Europæisk narrativ (dominerende frem til nyere tid): heroisk kristent forsvar og civilisationsprojekt. Islamisk narrativ: destruktiv invasion der aktiveres i kollektiv hukommelse som forløber for kolonialisme. Divergensen viser at historisk meningsdannelse er nutidsbestemt: korstogene blev centralt meningsbærende i arabisk politisk diskurs under europæisk imperialisme og Israel-Palæstina-konflikten — ikke som neutral historisk erindring men som politisk ressource","accepted_answers":["Europæisk narrativ (dominerende frem til nyere tid): heroisk kristent forsvar og civilisationsprojekt. Islamisk narrativ: destruktiv invasion der aktiveres i kollektiv hukommelse som forløber for kolonialisme. Divergensen viser at historisk meningsdannelse er nutidsbestemt: korstogene blev centralt meningsbærende i arabisk politisk diskurs under europæisk imperialisme og Israel-Palæstina-konflikten — ikke som neutral historisk erindring men som politisk ressource"],"review_text":"Carole Hillenbrand (The Crusades: Islamic Perspectives, 1999) dokumenterer at korstogene faktisk spillede en relativt marginal rolle i islamisk historiografi frem til 1800-tallet — det var europæisk imperialisme der genaktiverede dem som politisk symbol. Saladin (Salah ad-Din) var næsten glemt i islamisk tradition og blev genopfundet som nationalhelten i 19. århundredes arabisk nationalisme delvist under inspiration fra europæiske historiografiske romantiseringer. George Bushs talefejl om korstog i 2001 og Osama bin Ladens korstogs-retorik viser begge at historiografisk meningsdannelse er politisk ressource ikke neutral erindring. Paul Freedmans Images of the Medieval Peasant (1999) viser analogt at middelalderlige bønder i europæisk historiografi er set enten som primitiv masse eller romantiserede naturmennesker — begge konstruktioner tjener nutidsinteresser. Den metodologiske pointe: historiografisk analyse kræver at vi spørger hvem der konstruerer narrativet, hvornår og til hvilke formål."}$$::jsonb,
  'mc','short',$${"concepts":["korstogs-narrativer","islamisk historiografi","Hillenbrand","Saladin","politisk erindring","historiografisk konstruktion"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var korstogenes vigtigste langsigtede konsekvenser for forholdet mellem den islamiske verden og det kristne Europa?","options":["Korstogsperioden forstærkede snarere end skabte det religiøse skel: handel og intellektuel udveksling (arabisk matematik, filosofi og medicin til Europa via Spanien og Sicilien) fortsatte parallelt med krigshandlingerne. Den mest varige konsekvens var en traumatisk kollektiv hukommelse der aktiveres selektivt i politiske konflikter. Dichotomien civilisation-mod-islam er delvist en moderne konstruktion der projiceres tilbage — middelalderens faktiske relationer var mere komplekse og vekslende","Korstogene skabte et permanent og absolut religiøst fjendskab der gør enhver dialog og kulturel udveksling umulig frem til i dag","Korstogene havde ingen varig indflydelse på islamisk-kristent forhold og er historisk irrelevante for nutidig geopolitik og religiøs konflikt","Korstogene resulterede i fuldstændig islamisk sejr og europæisk tilbagetrækning der permanent ændrede Europas territoriale og kulturelle grænser"],"correct":"Korstogsperioden forstærkede snarere end skabte det religiøse skel: handel og intellektuel udveksling (arabisk matematik, filosofi og medicin til Europa via Spanien og Sicilien) fortsatte parallelt med krigshandlingerne. Den mest varige konsekvens var en traumatisk kollektiv hukommelse der aktiveres selektivt i politiske konflikter. Dichotomien civilisation-mod-islam er delvist en moderne konstruktion der projiceres tilbage — middelalderens faktiske relationer var mere komplekse og vekslende","accepted_answers":["Korstogsperioden forstærkede snarere end skabte det religiøse skel: handel og intellektuel udveksling (arabisk matematik, filosofi og medicin til Europa via Spanien og Sicilien) fortsatte parallelt med krigshandlingerne. Den mest varige konsekvens var en traumatisk kollektiv hukommelse der aktiveres selektivt i politiske konflikter. Dichotomien civilisation-mod-islam er delvist en moderne konstruktion der projiceres tilbage — middelalderens faktiske relationer var mere komplekse og vekslende"],"review_text":"Richard Southern (Western Views of Islam in the Middle Ages, 1962) og John Tolan (Saracens, 2002) dokumenterer at europæisk forståelse af islam i middelalderen var præget af ignorance, fantasi og polemik — men også af fascineret respekt for islamisk videnskab og filosofi. Arabisk viden i matematik (algebra, algoritmik), astronomi (astrolabiet), medicin (Ibn Sina/Avicenna) og filosofi (Ibn Rushd/Averroes) strømmede til Europa primært via Spanien (Toledo-oversættelsescentret) og Sicilien — ikke via korstogsstaterne. Venezias og Genuas handelsforbindelser med islamiske handelspartnere fortsatte uafbrudt under korstogene. Det analytisk vigtige: krig og kulturel udveksling udelukkede ikke hinanden i middelalderen. Den moderne binære islamisk-kristent konfrontations-narrativ er en retrospektiv konstruktion der sletter den faktiske kompleksitet."}$$::jsonb,
  'mc','short',$${"concepts":["korstogenes konsekvenser","kulturel udveksling","arabisk videnskab","Toledo","kollektiv hukommelse","Southern"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

-- ─── BAND 5 · KIRKE OG STAT (4 questions) ────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var den egentlige principielle kerne i investiturstriden (1076-1122) — og hvad viser Wormserkonkordatets kompromis om magtens grænser?","options":["Investiturstriden handlede om hvem der kontrollerede kirkeembeder og dermed kirkens politiske loyalitet: konger der nominerede og indsatte biskopper via ringe og stav (symbolsk investitur) kontrollerede de rigeste grundejere i riget. Gregors VII's program ville gøre kirken selvstyrende og uafhængig af verdslig kontrol. Wormserkonkordatets (1122) kompromis delte symbolerne men løste ikke grundspørgsmålet: kirkens institutionelle autonomi versus statens kontrol over dens rigdom og loyalitet","Investiturstriden var udelukkende et trivielt ceremonielt strid om symbolik uden reelle politiske eller principielle dimensioner af betydning","Investiturstriden endte i absolut kejserlig sejr og kirken fik ingen selvstændig magt efter Wormserkonkordatet i 1122","Investiturstriden var udelukkende en intern teologisk strid i kirken uden statslig dimension eller politisk konsekvens"],"correct":"Investiturstriden handlede om hvem der kontrollerede kirkeembeder og dermed kirkens politiske loyalitet: konger der nominerede og indsatte biskopper via ringe og stav (symbolsk investitur) kontrollerede de rigeste grundejere i riget. Gregors VII's program ville gøre kirken selvstyrende og uafhængig af verdslig kontrol. Wormserkonkordatets (1122) kompromis delte symbolerne men løste ikke grundspørgsmålet: kirkens institutionelle autonomi versus statens kontrol over dens rigdom og loyalitet","accepted_answers":["Investiturstriden handlede om hvem der kontrollerede kirkeembeder og dermed kirkens politiske loyalitet: konger der nominerede og indsatte biskopper via ringe og stav (symbolsk investitur) kontrollerede de rigeste grundejere i riget. Gregors VII's program ville gøre kirken selvstyrende og uafhængig af verdslig kontrol. Wormserkonkordatets (1122) kompromis delte symbolerne men løste ikke grundspørgsmålet: kirkens institutionelle autonomi versus statens kontrol over dens rigdom og loyalitet"],"review_text":"Biskopper var ikke blot åndelige ledere: de var store grundejere, militære vasaller og kongelige administratorer. Hvem der indsatte dem afgørende hvem de var loyale over for. Gregor VIIs Dictatus Papae (1075) proklamerede 27 punkter om pavens suverænitet inklusive ret til at afsætte kejsere — en direkte udfordring til den karolingiske tradition for kongens kontrol over kirken. Kejser Henrik IV's ydmygelse i Canossa (1077) da han stod barfodet i sne for at modtage absolution er det dramatiske symbol, men den politiske substans var kirkens forsøg på at skabe en juridisk og institutionel sfære fri for verdslig kontrol. Wormserkonkordatets løsning (scepter-symbolik for verdslig del, ring og stav for åndelig del) var et institutionelt kompromis der formaliserede den dobbelte loyalitet: biskopper skyldte paven åndelig og kejseren verdslig troskab. Brian Tierney (The Crisis of Church and State, 1964) viser at debatten definerede vestlig politisk tanke om separationen af religiøs og verdslig autoritet — et fundamentalt bidrag til den moderne stat."}$$::jsonb,
  'mc','short',$${"concepts":["investiturstriden","Gregor VII","Canossa","Wormserkonkordatet","kirkens autonomi","Tierney"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad definerede pavelig magt på dens højdepunkt under Innocens III (1198-1216) — og hvad er det strukturelle paradoks i pavelig universalpretension?","options":["Innocens III realiserede gregorianismens vision: han afsatte konger (England, Frankrig), proklamerede 4. korstog, sammenkaldte Laterankoncilet IV (1215) og kontrollerede kirkeembeder over hele Europa. Paradokset: pavelig universalmagt kræver stærke statsapparater til at gøre vedtag effektive, men stærke stater har incitament til at afvise pavelig indblanding — magtens institutionalisering indebærer dens grænse","Innocens IIIs magt var ubestridt og absolutt og hans periode viser at pavelig universalmagt er historisk bæredygtig på lang sigt","Innocens III var teologisk stærk men politisk svag og hans periode viser alene pavemagtens strukturelle begrænsninger","Pavens magt i middelalderen var udelukkende ceremoniel og ingen europæisk konger anerkendte faktisk pavelig autoritet over verdslige anliggender"],"correct":"Innocens III realiserede gregorianismens vision: han afsatte konger (England, Frankrig), proklamerede 4. korstog, sammenkaldte Laterankoncilet IV (1215) og kontrollerede kirkeembeder over hele Europa. Paradokset: pavelig universalmagt kræver stærke statsapparater til at gøre vedtag effektive, men stærke stater har incitament til at afvise pavelig indblanding — magtens institutionalisering indebærer dens grænse","accepted_answers":["Innocens III realiserede gregorianismens vision: han afsatte konger (England, Frankrig), proklamerede 4. korstog, sammenkaldte Laterankoncilet IV (1215) og kontrollerede kirkeembeder over hele Europa. Paradokset: pavelig universalmagt kræver stærke statsapparater til at gøre vedtag effektive, men stærke stater har incitament til at afvise pavelig indblanding — magtens institutionalisering indebærer dens grænse"],"review_text":"Innocens III (pave 1198-1216) er det klareste eksempel på gregorianismens politiske kulminationspunkt. Han tvang kong Johan af England til at anerkende England som pavelig lensbesiddelse efter konflikten om ærkebiskop Stephen Langton. Han ekskommunikerede Filip II af Frankrig over hans ægteskab. Hans Per Venerabilem-dekretale etablerede juridisk at paven havde ret til at dømme i verdslige sager ratio peccati (på grund af synd). Laterankoncilet IV (1215) var det mest ambitiøse kirke-koncil hidtil: obligatorisk skriftemål, transsubstantiation som dogme, forbud mod ny religiøs ordener, jødernes gule mærker. Men paradokset er strukturelt: Innocens IIIs sejre krævede at europæiske konger faktisk implementerede hans beslutninger — de havde militær og administrativ kapacitet han manglede. En stærkere pave producerede stærkere modstand. Bonifacius VIIIs Unam Sanctam (1302) forsøgte at gentage Innocens IIIs universalpretensioner — men Filips IV af Frankrig svarede med Anagni-episoden (fysisk anholdelse af paven) og det avignonske eksilpavedom. Magtens institutionalisering sætter præcis de betingelser for dens underminering."}$$::jsonb,
  'mc','short',$${"concepts":["Innocens III","Laterankoncilet IV","pavelig universalmagt","Unam Sanctam","Anagni","strukturelt paradoks"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad afslørede konflikten mellem Henrik II og Thomas Becket om magtforholdet mellem kirke og stat i middelalderens England?","options":["Konflikten (1162-70) eksponerede en strukturel spænding: Clarendon-konstitutionerne (1164) ville underordne gejstliges retssager under kongelig jurisdiktion og dermed eliminere kirkens juridiske autonomi. Beckets martyrium vendte styrkeforholdet: den internationale propagandamagt hos en martyrkirke overvandt kongens militære og administrative overlegenhed. Henrik IIs bodsgang i Canterbury (1174) viser at pavelig-kirkelig symbolsk kapital tvang kongelig politikkorrektur","Konflikten endte i absolut kongelig sejr og Clarendon-konstitutionerne forblev fuldt gældende uden religiøse modifikationer af nogen art","Konflikten var udelukkende en personlig strid mellem to gamle venner uden principielle dimensioner for forholdet mellem kirke og stat","Beckets martyrium var historisk irrelevant og påvirkede ikke Henrik IIs kirkepolitik på nogen målbar eller varig måde"],"correct":"Konflikten (1162-70) eksponerede en strukturel spænding: Clarendon-konstitutionerne (1164) ville underordne gejstliges retssager under kongelig jurisdiktion og dermed eliminere kirkens juridiske autonomi. Beckets martyrium vendte styrkeforholdet: den internationale propagandamagt hos en martyrkirke overvandt kongens militære og administrative overlegenhed. Henrik IIs bodsgang i Canterbury (1174) viser at pavelig-kirkelig symbolsk kapital tvang kongelig politikkorrektur","accepted_answers":["Konflikten (1162-70) eksponerede en strukturel spænding: Clarendon-konstitutionerne (1164) ville underordne gejstliges retssager under kongelig jurisdiktion og dermed eliminere kirkens juridiske autonomi. Beckets martyrium vendte styrkeforholdet: den internationale propagandamagt hos en martyrkirke overvandt kongens militære og administrative overlegenhed. Henrik IIs bodsgang i Canterbury (1174) viser at pavelig-kirkelig symbolsk kapital tvang kongelig politikkorrektur"],"review_text":"Clarendon-konstitutionerne (1164) var Henrik IIs forsøg på at kodificere og udvide kongelig kontrol over kirken: gejstlige anklaget for forbrydelser skulle stilles for kongelig ret, ikke kun kirkelige domstole. Becket (som Henrik selv havde udnævnt som ærkebiskop netop fordi han forventede loyalitet) modsatte sig dette konsekvent. Hans mord i Canterbury katedral den 29. december 1170 — udført af fire riddere der hørte kongens raseri — var det mediepolitiske vendepunkt. Kanoniseringen kom allerede i 1173 og Canterbury blev øjeblikkeligt Europas vigtigste pilgrimssted. Henrik IIs bodsgang (1174) — barfodet, pisket af munke — var ikke frivillig fromhed men politisk nødvendighed: at afvise martyrens kult var politisk selvmord. Frank Barlow (Thomas Becket, 1986) og Michael Staunton har dokumenteret at konflikten handlede om juridisk jurisdiktion — kirkens benefit of clergy-princip (gejstlige bedømt af kirkeret alene) versus statens krav om monopol på retshåndhævelse. Denne spænding var ikke løst i 1174 men vendte tilbage i hele Europas kirke-stat-relationer frem til Reformationen."}$$::jsonb,
  'mc','short',$${"concepts":["Henrik II","Thomas Becket","Clarendon-konstitutionerne","martyrium","benefit of clergy","symbolsk kapital"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad forklarede det avignonske pavedom (1309-1377) — og hvad var konsekvenserne for pavemagtens institutionelle legitimitet?","options":["Det avignonske pavedom fulgte Filips IVs systematiske underminering af Bonifacius VIIIs universalpretensioner (konflikten om kirkeskat og Unam Sanctam 1302). Clement Vs flytning til Avignon (1309) symboliserede pavemagtens afhængighed af det franske kongehus. Legitimitetskrisen var strukturel: Rom var Petrus-stolens traditionelle sted og et avignonsk pavedom fremstod som et redskab for franske dynastiinteresser snarere end universel kristen autoritet","Det avignonske pavedom var et frivilligt midlertidigt arrangement uden nogen konsekvenser for pavelig legitimitet og uafhængighed fra verdslig magt","Flytningen til Avignon styrkede pavemagtens autoritet ved at placere den i Europas daværende politiske og administrative centrum","Det avignonske pavedom er en historiografisk overdrivelse og paverne opholdt sig reelt i Rom det meste af perioden 1309-1377"],"correct":"Det avignonske pavedom fulgte Filips IVs systematiske underminering af Bonifacius VIIIs universalpretensioner (konflikten om kirkeskat og Unam Sanctam 1302). Clement Vs flytning til Avignon (1309) symboliserede pavemagtens afhængighed af det franske kongehus. Legitimitetskrisen var strukturel: Rom var Petrus-stolens traditionelle sted og et avignonsk pavedom fremstod som et redskab for franske dynastiinteresser snarere end universel kristen autoritet","accepted_answers":["Det avignonske pavedom fulgte Filips IVs systematiske underminering af Bonifacius VIIIs universalpretensioner (konflikten om kirkeskat og Unam Sanctam 1302). Clement Vs flytning til Avignon (1309) symboliserede pavemagtens afhængighed af det franske kongehus. Legitimitetskrisen var strukturel: Rom var Petrus-stolens traditionelle sted og et avignonsk pavedom fremstod som et redskab for franske dynastiinteresser snarere end universel kristen autoritet"],"review_text":"Konflikten om Clericis laicos (1296) og Unam Sanctam (1302) — Bonifacius VIIIs mest ekstreme universalpretension om at paven har magt over alle herskere — mødte Filips IVs svar med Anagni-episoden (1303): franske og italienske fjender af Bonifacius lod ham arrestere fysisk. Han døde måneder efter. Clement V (en franskmand) valgte Avignon i 1309 frem for et kaotisk og farligt Rom. Det avignonske pavedoms syv paver var alle franske og udnævnte primært franske kardinaler — en nationalisering af hvad der pretenderede at være en universel institution. Petrarcas betegnelse Babylonisk fangenskab og Brigida af Svedens visionære kritik af det avignonske pavedom viser at legitimitetsproblemet var bredt anerkendt. Afslutningen 1377 (Gregor XI returnerer til Rom) efterfulgtes af det Store Skisma (1378-1417) med to og siden tre samtidige paver — en direkte konsekvens af den institutionelle svækkelse. Yves Renouards The Avignon Papacy (1970) viser at Avignon paradoksalt nok var administrativt effektivt men politisk delegitimerende."}$$::jsonb,
  'mc','short',$${"concepts":["avignonsk pavedom","Filips IV","Unam Sanctam","Anagni","Babylonisk fangenskab","Store Skisma"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

-- ─── BAND 5 · FEUDALISME (4 questions) ───────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var feudalsystemet primært et undertrykkelsesapparat — eller opfyldte det en funktionelt nødvendig rolle i middelalderens politisk ustabile omgivelser?","options":["Begge analyser er kontekstafhængigt valide: feudale forpligtelser (herremandens beskyttelse mod vikinger, plyndrende hære og andre truende aktører; bønders sikring af jord og husly i perioder med svag centralstat) opfyldte reelle funktioner. Men forpligtelserne var systematisk asymmetriske: bønder leverede arbejde, afgifter og militærtjeneste mens herrernes beskyttelsesydelse var variabel og afhængig af magt. Georges Duby viser strukturel udbytning, Marc Bloch at feudalismen indbandt magthavere i gensidig forpligtelse — begge dimensioner er nødvendige","Feudalisme var udelukkende et stabilt og gensidigt fordelagtigt system der opfyldte alle parters interesser optimalt og retfærdigt","Feudalisme var udelukkende systematisk undertrykkelse uden nogen funktionel legitimation, gensidighed eller historisk nødvendighed","Feudalisme er et historiografisk konstrukt der ikke reflekterer middelalderens faktiske sociale organisering og bør opgives som analytisk begreb"],"correct":"Begge analyser er kontekstafhængigt valide: feudale forpligtelser (herremandens beskyttelse mod vikinger, plyndrende hære og andre truende aktører; bønders sikring af jord og husly i perioder med svag centralstat) opfyldte reelle funktioner. Men forpligtelserne var systematisk asymmetriske: bønder leverede arbejde, afgifter og militærtjeneste mens herrernes beskyttelsesydelse var variabel og afhængig af magt. Georges Duby viser strukturel udbytning, Marc Bloch at feudalismen indbandt magthavere i gensidig forpligtelse — begge dimensioner er nødvendige","accepted_answers":["Begge analyser er kontekstafhængigt valide: feudale forpligtelser (herremandens beskyttelse mod vikinger, plyndrende hære og andre truende aktører; bønders sikring af jord og husly i perioder med svag centralstat) opfyldte reelle funktioner. Men forpligtelserne var systematisk asymmetriske: bønder leverede arbejde, afgifter og militærtjeneste mens herrernes beskyttelsesydelse var variabel og afhængig af magt. Georges Duby viser strukturel udbytning, Marc Bloch at feudalismen indbandt magthavere i gensidig forpligtelse — begge dimensioner er nødvendige"],"review_text":"Marc Blochs Feudal Society (1939-40) er stadig det grundlæggende referenceværk. Bloch betonede det gensidige element i feudale forpligtelser: vasallen skyldte militærtjeneste og rådgivning, herren skyldte beskyttelse og retfærdighed. I en periode med carolingisk sammenbrud og vikingangreb (800-950) var lokal militær beskyttelse en reel og værdifuld ydelse. Georges Dubys Three Orders (1980) viser at den ideologiske treenighed (dem der beder, dem der kæmper, dem der arbejder) retfærdiggjorde en ekstremt asymmetrisk fordeling: bøndernes arbejde finansierede adelens krig og kirkens bøn. Susan Reynolds (Fiefs and Vassals, 1994) udfordrede selve begrebet feudalisme og hævdede at middelalderlige historikere konstruerede et sammenhængende system der faktisk var lokalt variabelt og inkonsistent. Pointen er analytisk vigtig: feudalisme som systembegrebet er delvist en efterrationalisering — de faktiske relationer var mere kaotiske og situationsbestemte. Alligevel er den funktionelle analyse valid: i politisk kaos producerede lokale beskyttelsesrelationer reel sikkerhed, uanset om de var ideologisk retfærdiggjorte som feudale."}$$::jsonb,
  'mc','short',$${"concepts":["feudalisme","Bloch","Duby","Reynolds","undertrykkelse vs stabilitet","gensidighed"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Havde middelalderens bønder reel handlekraft og politisk bevidsthed — og hvad viser forskningen om aktørperspektivet?","options":["Nyere forskning afviser billedet af middelalderens bønder som passive ofre: de organiserede oprør (Watt Tylers bondeoprør 1381, Jacquerie 1358), udnyttede Sortedødens demografiske konsekvenser til lønforhandling og udnyttede manorialjuridiske processer til deres fordel. James Scotts weapons of the weak-analyse er historisk verificerbar: hverdagsmodstand (langsomhed, tyveri, sabotage, sladder) var systematisk og bevidst. Paul Freedman dokumenterer at bønder brugte religiøse og juridiske argumenter der viser politisk-etisk refleksion","Middelalderens bønder manglede ethvert politisk bevidsthed og handlekraft og var fuldt underkastet herremandens vilje uden mulighed for modstand","Bondeoprørene i middelalderen var så sjældne og lokale at de ikke kan bruges som bevis for generel bønders politisk bevidsthed eller handlekraft","Forskning om bønders handlekraft er anakronistiske projektioner af moderne politisk bevidsthed ind i en middelalderkontekst der ikke kender individualisme"],"correct":"Nyere forskning afviser billedet af middelalderens bønder som passive ofre: de organiserede oprør (Watt Tylers bondeoprør 1381, Jacquerie 1358), udnyttede Sortedødens demografiske konsekvenser til lønforhandling og udnyttede manorialjuridiske processer til deres fordel. James Scotts weapons of the weak-analyse er historisk verificerbar: hverdagsmodstand (langsomhed, tyveri, sabotage, sladder) var systematisk og bevidst. Paul Freedman dokumenterer at bønder brugte religiøse og juridiske argumenter der viser politisk-etisk refleksion","accepted_answers":["Nyere forskning afviser billedet af middelalderens bønder som passive ofre: de organiserede oprør (Watt Tylers bondeoprør 1381, Jacquerie 1358), udnyttede Sortedødens demografiske konsekvenser til lønforhandling og udnyttede manorialjuridiske processer til deres fordel. James Scotts weapons of the weak-analyse er historisk verificerbar: hverdagsmodstand (langsomhed, tyveri, sabotage, sladder) var systematisk og bevidst. Paul Freedman dokumenterer at bønder brugte religiøse og juridiske argumenter der viser politisk-etisk refleksion"],"review_text":"Rodney Hilton (Bond Men Made Free, 1973) og Paul Freedmans Images of the Medieval Peasant (1999) er de to vigtigste revisioner af den passive bonde-narrativ. Hilton viste at engelske bondeoprør ikke var spontane irrationelle eksplosioner men organiserede med klare politiske krav (afskaffelse af vilkårlig afgifter, personlig frihed). Watt Tylers oprør (1381) fremlagde præcise krav over for Richard II i Mile End-mødet. Jacquerie (1358) i Frankrig var en reaktion på adlens svigt under Hundredårskrigen kombineret med skattetryk. James Scotts Weapons of the Weak (1985) — baseret på moderne malaysisk landsbyforskning — er metodologisk overordnet: hverdagsmodstand er den normale form for politisk modstand for underprivilegerede grupper der ikke har adgang til åben konfrontation. Den er svær at dokumentere i middelalderlige kilder fordi den er usynlig for registrering. Men den er ikke fraværende. Freedman viser at middelalderlige bønder brugte det teologiske argument om fælles ophav fra Adam (Vor alle er Adams børn) som et etisk-juridisk argument mod livegenskab — et argument der kræver abstrakt moralsk-politisk tænkning."}$$::jsonb,
  'mc','short',$${"concepts":["bønders handlekraft","Watt Tyler","Jacquerie","Scott","Freedman","Hilton"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er sammenligningspotentialet og begrænsningerne ved at sammenligne feudale forpligtelsesstrukturer med moderne velfærdsstaters sociale kontrakt?","options":["Analogien har begrænset analytisk værdi: begge systemer involverer en udveksling af ydelse mod ydelse (skatter og militærtjeneste mod beskyttelse; skatter mod velfærdsydelser). Men den afgørende forskel er legitimitetsprincip og frivillighed: feudal forpligtelse bygger på personlig troskabsed og nedarvede relationer man ikke kan vælge sig ud af, mens velfærdsstaten bygger på demokratisk samtykke og universelle rettigheder der gælder uanset personlig troskab","Feudale forpligtelsesstrukturer er fuldstændig analoge med moderne velfærdsstater og sammenligningen er direkte og metodologisk uproblematisk","Der er ingen analytisk meningsfuld sammenligning mulig between feudalisme og moderne velfærdsstater da konteksterne er for fundamentalt forskellige til at belyse hinanden","Feudalisme er et overlegent stabilt system der burde overvejes genoprette som alternativ til moderne velfærdsstaters ineffektivitet og skattebyrderne"],"correct":"Analogien har begrænset analytisk værdi: begge systemer involverer en udveksling af ydelse mod ydelse (skatter og militærtjeneste mod beskyttelse; skatter mod velfærdsydelser). Men den afgørende forskel er legitimitetsprincip og frivillighed: feudal forpligtelse bygger på personlig troskabsed og nedarvede relationer man ikke kan vælge sig ud af, mens velfærdsstaten bygger på demokratisk samtykke og universelle rettigheder der gælder uanset personlig troskab","accepted_answers":["Analogien har begrænset analytisk værdi: begge systemer involverer en udveksling af ydelse mod ydelse (skatter og militærtjeneste mod beskyttelse; skatter mod velfærdsydelser). Men den afgørende forskel er legitimitetsprincip og frivillighed: feudal forpligtelse bygger på personlig troskabsed og nedarvede relationer man ikke kan vælge sig ud af, mens velfærdsstaten bygger på demokratisk samtykke og universelle rettigheder der gælder uanset personlig troskab"],"review_text":"Kontrafaktisk og komparativ historisk analyse er et vigtigt metodisk redskab men kræver præcision om hvad der sammenlignes og hvad der adskiller. Det fælles element: sociale kontrakter involverer immer en ydelse-mod-ydelse-struktur og en definition af hvem der inkluderes. Feudalismens eksklusion: livegne (servi) var juridisk bundet til jordet og kunne ikke forhandle frit — de var ikke parter i en kontrakt men ejendom. Velfærdsstaten (T.H. Marshalls civil, politisk og social citizenship, 1950) bygger på universel inklusion: alle borgere har rettigheder der ikke er betinget af personlig troskab eller herkomst. John Rawls (A Theory of Justice, 1971) og sociale kontraktteoretikere ser retfærdige sociale institutioner som hvad rationelle aktører ville vælge bag et uvidenhedens slør — en legitimitetsteori der er radikalt forskellig fra feudal personalisme. Sammenligningen er analytisk frugtbar præcis fordi den belyser hvad vi tager for givet ved moderne institutioner: universalitet, valg og rettigheder snarere end pligt, arv og troskab."}$$::jsonb,
  'mc','short',$${"concepts":["feudale forpligtelser","social kontrakt","Marshall","Rawls","legitimitetsprincip","komparativ analyse"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad forklarede feudalismens gradvise opløsning i senmiddelalderen — og hvad er historikernes debat om de afgørende årsager?","options":["Multi-kausal: Sortedøden (1347-51) radikalt ændrede arbejdsmarkedet ved at dræbe 30-50% af befolkningen og tvinge herremænd til bedre vilkår for at fastholde arbejdskraft. Stigende pengeøkonomi erstattede naturaliebaserede forpligtelser. Centralstatens styrkelse (engelske og franske konger) underminerede de mellemliggende herrers magt. Robert Brenners debat med Guy Bois viser at krisen har markedsøkonomiske og klasserelationsbaserede forklaringer der supplerer hinanden","Feudalisme blev afskaffet i et enkelt brud ved Sortedøden der automatisk og øjeblikkeligt producerede frie arbejdsmarkedsrelationer","Feudalisme ophørte udelukkende som følge af intellektuelle idéhistoriske ændringer uden materielle demografiske eller strukturelle faktorer","Feudalisme overlevede uforandret helt frem til Den Franske Revolution i 1789 og opløstes da som ren politisk beslutning"],"correct":"Multi-kausal: Sortedøden (1347-51) radikalt ændrede arbejdsmarkedet ved at dræbe 30-50% af befolkningen og tvinge herremænd til bedre vilkår for at fastholde arbejdskraft. Stigende pengeøkonomi erstattede naturaliebaserede forpligtelser. Centralstatens styrkelse (engelske og franske konger) underminerede de mellemliggende herrers magt. Robert Brenners debat med Guy Bois viser at krisen har markedsøkonomiske og klasserelationsbaserede forklaringer der supplerer hinanden","accepted_answers":["Multi-kausal: Sortedøden (1347-51) radikalt ændrede arbejdsmarkedet ved at dræbe 30-50% af befolkningen og tvinge herremænd til bedre vilkår for at fastholde arbejdskraft. Stigende pengeøkonomi erstattede naturaliebaserede forpligtelser. Centralstatens styrkelse (engelske og franske konger) underminerede de mellemliggende herrers magt. Robert Brenners debat med Guy Bois viser at krisen har markedsøkonomiske og klasserelationsbaserede forklaringer der supplerer hinanden"],"review_text":"Brenner-debatten (Past and Present, 1976-82) er det vigtigste akademiske opgør om feudalismens krise. Guy Bois argumenterede for at feudalismens krise havde strukturelle markedsøkonomiske årsager: konkurrencetrykket fra voksende pengeøkonomi underminerede naturalieøkonomiens forpligtelsessystem. Robert Brenner afviste markedsforklaringen og argumenterede for at klasserelationer og klassekampens resultat var afgørende: i England lykkedes det bønderne delvist at frigøre sig via bondeoprør og demografisk pres, mens det i Østeuropa mislykkedes og resulterede i second serfdom (genindførelse af livegenskab). Sortedødens demografiske effekt er velkendt: lønningerne i England steg med 40-100% i årtiet efter pesten ifølge Bruce Campbells England: Before the Black Death (2000) og Statute of Laborers (1351) — et forsøg på tvangsmæssigt at fastfryse lønninger — viser at markedskræfterne pressede feudale forpligtelser. Pengeøkonomiens vækst (Hansaforbundet, Firenzes bankcentre) var parallel og forstærkende. Multi-kausalitet er den eneste analytisk forsvarlige position."}$$::jsonb,
  'mc','short',$${"concepts":["feudalismens opløsning","Brenner-debatten","Sortedøden","pengeøkonomi","centralstat","Bois"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

-- ─── BAND 5 · SORTEDØDEN OG SAMFUND (4 questions) ────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var Sortedødens mest varige sociale og ekonomiske konsekvenser — og hvad er det analytisk vigtige paradoks?","options":["Paradokset: Sortedøden (1347-51) var den største demografiske katastrofe i europæisk historie (25-50 millioner døde, 30-60% af befolkningen i ramte regioner) men producerede langsigtede sociale forbedringer for de overlevende: lønningerne steg drastisk da arbejdskraft blev knap, jordjord blev billig og tilgængelig, feudale forpligtelser eroderede og social mobilitet steg markant. Katastrofe og social acceleration kan sameksistere — demografisk kollaps kan bryde strukturelle blokeringer","Sortedøden havde ingen varige sociale konsekvenser og samfundene vendte hurtigt og fuldstændig tilbage til præpest status quo inden for en enkelt generation","Sortedøden var socialt og ekonomisk katastrofal for alle overlevende i alle samfundsklasser uden nogen positive konsekvenser af nogen art","Sortedødens primære og eneste varige konsekvens var religiøs nihilisme der permanent og totalt underminerede kristen tro og kirkelig autoritet i Vesteuropa"],"correct":"Paradokset: Sortedøden (1347-51) var den største demografiske katastrofe i europæisk historie (25-50 millioner døde, 30-60% af befolkningen i ramte regioner) men producerede langsigtede sociale forbedringer for de overlevende: lønningerne steg drastisk da arbejdskraft blev knap, jordjord blev billig og tilgængelig, feudale forpligtelser eroderede og social mobilitet steg markant. Katastrofe og social acceleration kan sameksistere — demografisk kollaps kan bryde strukturelle blokeringer","accepted_answers":["Paradokset: Sortedøden (1347-51) var den største demografiske katastrofe i europæisk historie (25-50 millioner døde, 30-60% af befolkningen i ramte regioner) men producerede langsigtede sociale forbedringer for de overlevende: lønningerne steg drastisk da arbejdskraft blev knap, jordjord blev billig og tilgængelig, feudale forpligtelser eroderede og social mobilitet steg markant. Katastrofe og social acceleration kan sameksistere — demografisk kollaps kan bryde strukturelle blokeringer"],"review_text":"David Herlihy (The Black Death and the Transformation of the West, 1997) og Bruce Campbell (The Great Transition, 2016) viser at pesten ramte et Europa der allerede var under demografisk og klimatisk pres (Den Lille Istid fra ca. 1300). Præpest-Europa var Malthusiansk overpopuleret: jordpriserne var høje, lønningerne lave, og marginallandbruget udbredt. Pesten kollapsede dette ligevægtspunkt og forskød magt fra jord til arbejde. Engelsk real-løn (inflationsjusteret) steg med 40-80% i perioden 1350-1450 ifølge Robert Allens historiske lønserier. Statute of Laborers (1351) — et kongelig dekret der forsøgte at fastfryse lønninger på præ-pest niveau — viser at magthaverne var klar over den strukturelle transformation og aktivt modvirkede den. De nye muligheder var dog socialt selektive: ufaglærte bønder fik bedre jordvilkår, men kvinder og minoriteter oplevede ikke proportionalt samme løft. Det analytisk vigtige paradoks er metodologisk: kortsigtede katastrofer og langsigtede forbedringer er ikke modsætninger men kan være kausalt forbundne."}$$::jsonb,
  'mc','short',$${"concepts":["Sortedøden","demografisk kollaps","lønstigning","social mobilitet","Herlihy","Campbell"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser forskningen om kvinders magt og handlekraft i middelalderen — og hvad er den metodologiske udfordring ved at undersøge det?","options":["Nyere forskning afviser den rene offernarrativ: kvinder udøvede indflydelse som abbedisser (Hildegard af Bingen med videnskabelig og teologisk autoritet), som regensdronninger (Margrethe I af Danmark-Norge-Sverige), som handelsdrivende i Hansabyerne og som mystikere med geistlig autoritet der oversteg mandlige gejstliges. Den metodologiske udfordring er fundamental: kilderne er skrevet primært af og for mænd og kvinders handlinger er systematisk underregistreret og fortolkningsfarvet af patriarkalske antagelser om passivitet","Middelalderens kvinder var fuldstændigt magtesløse og enhver tale om kvindelig handlekraft er anakronistisk projektion af moderne feministiske ideer","Middelalderens kvinder havde fuld politisk juridisk og social ligestilling med mænd og kønsdiskrimination var et modernitets-fænomen","Kun abbedisser og regensdronninger havde nogen form for social handlekraft og andre kvinder er helt irrelevante for en historiografisk analyse af middelalderlig magt"],"correct":"Nyere forskning afviser den rene offernarrativ: kvinder udøvede indflydelse som abbedisser (Hildegard af Bingen med videnskabelig og teologisk autoritet), som regensdronninger (Margrethe I af Danmark-Norge-Sverige), som handelsdrivende i Hansabyerne og som mystikere med geistlig autoritet der oversteg mandlige gejstliges. Den metodologiske udfordring er fundamental: kilderne er skrevet primært af og for mænd og kvinders handlinger er systematisk underregistreret og fortolkningsfarvet af patriarkalske antagelser om passivitet","accepted_answers":["Nyere forskning afviser den rene offernarrativ: kvinder udøvede indflydelse som abbedisser (Hildegard af Bingen med videnskabelig og teologisk autoritet), som regensdronninger (Margrethe I af Danmark-Norge-Sverige), som handelsdrivende i Hansabyerne og som mystikere med geistlig autoritet der oversteg mandlige gejstliges. Den metodologiske udfordring er fundamental: kilderne er skrevet primært af og for mænd og kvinders handlinger er systematisk underregistreret og fortolkningsfarvet af patriarkalske antagelser om passivitet"],"review_text":"Judith Bennett (Women in the Medieval English Countryside, 1987) og Sharon Farmer (Surviving Poverty in Medieval Paris, 2002) har grundlæggende revideret billedet. Bennett viser at kvinder i engelske landsbyer aktivt deltog i markedstransaktioner, ejede ejendom og brugte manorialkurser. Hildegard af Bingen (1098-1179) er den mest ekstraordinære case: hun formulerede teologi, naturvidenskab og musik der cirkulation gennem Europa og korresponderede med paver, kejsere og biskopper med en autoritet der var ekstraordinær for enhver — endsige en kvinde. Carolyne Larringtons kvindestudier af nordisk middelalder viser at Margarethe I (regent 1387-1412) konsoliderede tre nordiske riger med dygtighed der oversteg de fleste mandlige konger. Den metodologiske udfordring er Joan Scotts Gender and the Politics of History (1988): kilderne er ikke neutrale registre over historisk aktivitet men produkter af mandlige skribenter med forestillinger om kvinders passivitet der styrer hvad der registreres og hvordan. Fravær af kvinder i kilderne er ikke bevis for fravær fra historien."}$$::jsonb,
  'mc','short',$${"concepts":["kvinder og magt","Hildegard af Bingen","Margrethe I","Bennett","Scott","kildekritik"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad drev den middelalderlige urbanisering fra ca. 1000-1300 — og hvad er dens strukturelle konsekvenser for det europæiske samfund?","options":["Urbaniseringen havde multiple drivkræfter: teknologisk (trevangsbrug og vandmøller øgede landbrugsoverskud), handelsmæssig (genopvågnet Middelhavshandel, Hansaforbundets nordeuropæiske netværk), institutionel (biskoppernes katedral-byer, den frihed der tilkom byboere via stadsprivilegier). Konsekvenserne var strukturelt transformative: borgerskabet opstod som ny social klasse der ikke passede ind i treenigheds-ideologien, guild-institutioner skabte alternativ til feudalt hierarki, og universiteter producerede en ny intellektuel klasse","Middelalderlig urbanisering var rent befolkningsdrevet og uden strukturelle sociale konsekvenser ud over større koncentrationer af eksisterende sociale klasser","Middelalderlige byer var politisk og socialt irrelevante i en periode fuldstændigt domineret af landdistrikter og feudal organisation","Urbaniseringen i middelalderen var begrænset til Norditalien og havde ingen bredere europæisk relevans for samfundsstruktur og social forandring"],"correct":"Urbaniseringen havde multiple drivkræfter: teknologisk (trevangsbrug og vandmøller øgede landbrugsoverskud), handelsmæssig (genopvågnet Middelhavshandel, Hansaforbundets nordeuropæiske netværk), institutionel (biskoppernes katedral-byer, den frihed der tilkom byboere via stadsprivilegier). Konsekvenserne var strukturelt transformative: borgerskabet opstod som ny social klasse der ikke passede ind i treenigheds-ideologien, guild-institutioner skabte alternativ til feudalt hierarki, og universiteter producerede en ny intellektuel klasse","accepted_answers":["Urbaniseringen havde multiple drivkræfter: teknologisk (trevangsbrug og vandmøller øgede landbrugsoverskud), handelsmæssig (genopvågnet Middelhavshandel, Hansaforbundets nordeuropæiske netværk), institutionel (biskoppernes katedral-byer, den frihed der tilkom byboere via stadsprivilegier). Konsekvenserne var strukturelt transformative: borgerskabet opstod som ny social klasse der ikke passede ind i treenigheds-ideologien, guild-institutioner skabte alternativ til feudalt hierarki, og universiteter producerede en ny intellektuel klasse"],"review_text":"Robert Lopez (The Commercial Revolution of the Middle Ages, 1971) dokumenterede at Europa oplevede en handels- og demografisk eksplosion fra 950-1300: Europas befolkning voksede fra ca. 25 til ca. 75 millioner. Byerne voksede parallelt: Paris nåede 200.000 indbyggere ca. 1300, London 80.000, Venedig og Genova over 100.000. Det tyske retsprin-cip Stadtluft macht frei (byluft gør fri) — at livegne der opholdt sig i en by et år og en dag var juridisk frie — viser at byers institutionelle status var radikalt anderledes end landområdernes. Hansaforbundet (grundlagt 1241) organiserede nordeuropæisk handel fra Novgorod til London i et netværk der overskred feudale loyaliteter. Guildsystemet regulerede produktion og handel og skabte sociale institutioner (gilder, laug) der fungerede parallelt med kirkens og adelens institutioner. Henri Pirennes Medieval Cities (1925) — tesen om at handel og byernes opkomst brød feudalismens lukkethed — er fortsat det analytiske udgangspunkt, omend Pirenne overvurderede handlende som motor og undervurderede institutionelle faktorer."}$$::jsonb,
  'mc','short',$${"concepts":["urbanisering","Hansaforbundet","borgerskab","Lopez","Pirenne","Stadtluft macht frei"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var de langsigtede demografiske konsekvenser af Sortedøden — og hvilke strukturelle mekanismer forklarer den langsomme demografiske genopretning?","options":["Europa nåede ikke præ-pest befolkningsniveauer igen før ca. 1500-1550. Forklaringerne er sammensatte: gentagne pestbølger (1361, 1374, 1382 etc.) forhindrede genopretning da pesten var endemisk i europæiske råttebestande. Den langsom genopretning transformerede grundlæggende europæisk agrarstruktur: Wüstungen (øde landbyer) i Tyskland vidner materielt om permanente bosætningstab. David Herlihy argumenterer at den demografiske krise paradoksalt åbnede for teknologisk og institutionel innovation","Europa genoprettede sin præ-pest befolkning inden for 30 år og den demografiske katastrofe havde ingen varig strukturel konsekvens for agrar- eller bysamfund","Sortedøden eliminerede permanent europæisk befolkningsvækst og Europa nåede aldrig igen præ-pest befolkningsniveauer frem til industrialiseringen","Sortedødens demografiske konsekvenser er dramatisk overdrevet i historiografien og de faktiske befolkningstab var marginale og lokale"],"correct":"Europa nåede ikke præ-pest befolkningsniveauer igen før ca. 1500-1550. Forklaringerne er sammensatte: gentagne pestbølger (1361, 1374, 1382 etc.) forhindrede genopretning da pesten var endemisk i europæiske råttebestande. Den langsom genopretning transformerede grundlæggende europæisk agrarstruktur: Wüstungen (øde landbyer) i Tyskland vidner materielt om permanente bosætningstab. David Herlihy argumenterer at den demografiske krise paradoksalt åbnede for teknologisk og institutionel innovation","accepted_answers":["Europa nåede ikke præ-pest befolkningsniveauer igen før ca. 1500-1550. Forklaringerne er sammensatte: gentagne pestbølger (1361, 1374, 1382 etc.) forhindrede genopretning da pesten var endemisk i europæiske råttebestande. Den langsom genopretning transformerede grundlæggende europæisk agrarstruktur: Wüstungen (øde landbyer) i Tyskland vidner materielt om permanente bosætningstab. David Herlihy argumenterer at den demografiske krise paradoksalt åbnede for teknologisk og institutionel innovation"],"review_text":"Den demografiske genopretning efter 1348-51 var langt langsommere end man tidligere antog. Ole Benedictow (The Black Death 1346-1353: The Complete History, 2004) estimerer pesttabene til 50-60% af Europas befolkning — højere end ældre estimater. Gentagne pestbølger: 1361 (den anden pest, særlig hård for børn der ikke havde overlevende forældre immuniserede), 1374, 1382 og derefter ca. hvert 10.-15. år frem til ca. 1720 holdt befolkningstallet nede. Wüstungen er det arkæologiske bevis: hundredvis af tyske og skandinaviske landsbyer blev permanent forladt i perioden 1350-1450 og er aldrig genbesat. Bruce Campbell (The Great Transition, 2016) argumenterer at pesten kombineret med Den Lille Istids klimatisk forværring (koldere, vådere vejr) skabte det 14.-15. århundredes almene krise. Herlihys analytisk vigtigste pointe: den demografiske krise brød Malthusiansk ligevægt og skabte en tilstand der fremmede teknologisk substitution for arbejdskraft — trykpressen (1450erne), vandmøller og vinddrevne maskiner vandt frem præcis i den demografisk svage periode."}$$::jsonb,
  'mc','short',$${"concepts":["demografisk genopretning","Wüstungen","Benedictow","Campbell","Herlihy","Lille Istid"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

-- ─── BAND 5 · HISTORIOGRAFI OG MODERNE RELEVANS (4 questions) ────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er begrebet 'Mørke Middelalder' historiografisk legitimt — og hvad afslører debatten om periodiseringens politiske og ideologiske funktion?","options":["'Mørke Middelalder' er en renæssancekonstruktion (Petrarcas saeculum obscurum) der tjente renæssancens selvforståelse som genfødsel og afvisning af det foregående. Moderne forskning viser at middelalderen producerede afgørende innovation: skolastik, universiteter, gotisk arkitektur, juridisk systematik, arabisk vidensoverlevering. Periodiseringens politiske funktion: progressiv historiefortælling legitimerede humanisternes selvforståelse som kulturreddere — mørket var nødvendigt for at renæssancen kunne lyse","'Mørke Middelalder' er et fuldt historisk korrekt begreb og middelalderen var faktisk en periode med næsten nul intellektuel og kulturel produktion","Renæssancens historikere formulerede 'Mørke Middelalder' som et neutralt deskriptivt begreb uden nogen ideologisk funktion eller politisk agenda","Begrebet 'Mørke Middelalder' er et moderne fænomen og ingen middelalderlige eller tidlig-renæssance-historikere brugte det eller noget lignende"],"correct":"'Mørke Middelalder' er en renæssancekonstruktion (Petrarcas saeculum obscurum) der tjente renæssancens selvforståelse som genfødsel og afvisning af det foregående. Moderne forskning viser at middelalderen producerede afgørende innovation: skolastik, universiteter, gotisk arkitektur, juridisk systematik, arabisk vidensoverlevering. Periodiseringens politiske funktion: progressiv historiefortælling legitimerede humanisternes selvforståelse som kulturreddere — mørket var nødvendigt for at renæssancen kunne lyse","accepted_answers":["'Mørke Middelalder' er en renæssancekonstruktion (Petrarcas saeculum obscurum) der tjente renæssancens selvforståelse som genfødsel og afvisning af det foregående. Moderne forskning viser at middelalderen producerede afgørende innovation: skolastik, universiteter, gotisk arkitektur, juridisk systematik, arabisk vidensoverlevering. Periodiseringens politiske funktion: progressiv historiefortælling legitimerede humanisternes selvforståelse som kulturreddere — mørket var nødvendigt for at renæssancen kunne lyse"],"review_text":"Petrarca (Francesco Petrarch, 1304-74) introducerede mørkets metafor om perioden efter Roms fald: klassisk latinsk kultur var lys, det der fulgte var mørke frem til dens genoplivelse i hans samtid. Idéen greb fat og Vasaris Lives of the Artists (1550) befæstede en narrativ om kunstens genfødsel efter middelalderens forfald. David Lindberg (The Beginnings of Western Science, 1992) og Michael Shank's Science and Religion: A Historical Introduction (2002) viser at middelalderlig videnskab — Roger Bacons empirisk-optiske studier, Grossetestes matematiske naturfilosofi, islamisk-influerede astronomiske beregninger — var substantiel. Universiteterne i Bologna (1088), Oxford (1096) og Paris (ca. 1150) er middelalderlige institutioner der lever i dag. Gotikken er en arkitektonisk og ingeniørmæssig bedrift (flyvende støttebuer der muliggjorde høje hvælv og store vinduer) der var teknologisk avanceret. Umberto Ecos The Name of the Rose og medievalistikken generelt har rehabiliteret billedet. Den metodologiske lektion: periodiseringer er aldrig neutrale — de konstrueres til at tjene narrativer om fremgang, forfald og genfødsel der er politisk formålstjenlige."}$$::jsonb,
  'mc','short',$${"concepts":["Mørke Middelalder","Petrarca","periodisering","Lindberg","middelalderlig innovation","historiografisk konstruktion"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvilke middelalderlige institutioner har den stærkeste levedygtige arv i europæiske moderne samfund — og hvad viser dette om institutionel kontinuitet?","options":["Universitetet (Bologna 1088, Oxford ca. 1096, Paris ca. 1150) er den mest robuste middelalderinstitution med ubrudt kontinuitet. Common law-systemet er den engelske medievale juridiske arv. Parlamentarisme startede som middelalderlig rådsrepræsentation (Magna Carta 1215, engelske parlamenter). Harold Bermanns Law and Revolution viser at moderne vestlig retsorden er grundlæggende formgivet af middelalderlig kanonisk og romerretslig tradition. Institutionel kontinuitet er ikke en tilfældig restbeholdning men et strukturelt fænomen","Ingen middelalderlige institutioner har overlevende relevans for moderne europæiske samfund da alle relevante institutioner blev opfundet eller radikalt reformeret i renæssancen og oplysningen","Middelalderens institutioner er komplet usammenlignelige med moderne institutioner og enhver analogislutning er anakronistisk og metodologisk uacceptabel","Universitetet er den eneste middelalderlige institution med varig relevans og alle andre institutioner er moderne opfindelser uden medievel rødder"],"correct":"Universitetet (Bologna 1088, Oxford ca. 1096, Paris ca. 1150) er den mest robuste middelalderinstitution med ubrudt kontinuitet. Common law-systemet er den engelske medievale juridiske arv. Parlamentarisme startede som middelalderlig rådsrepræsentation (Magna Carta 1215, engelske parlamenter). Harold Bermanns Law and Revolution viser at moderne vestlig retsorden er grundlæggende formgivet af middelalderlig kanonisk og romerretslig tradition. Institutionel kontinuitet er ikke en tilfældig restbeholdning men et strukturelt fænomen","accepted_answers":["Universitetet (Bologna 1088, Oxford ca. 1096, Paris ca. 1150) er den mest robuste middelalderinstitution med ubrudt kontinuitet. Common law-systemet er den engelske medievale juridiske arv. Parlamentarisme startede som middelalderlig rådsrepræsentation (Magna Carta 1215, engelske parlamenter). Harold Bermanns Law and Revolution viser at moderne vestlig retsorden er grundlæggende formgivet af middelalderlig kanonisk og romerretslig tradition. Institutionel kontinuitet er ikke en tilfældig restbeholdning men et strukturelt fænomen"],"review_text":"Harold Berman (Law and Revolution: The Formation of the Western Legal Tradition, 1983) er det mest ambitiøse argument for middelalderlig institutionel arv: den westlige juridiske tradition med dens forestilling om rettens autonomi over for politisk magt, juridisk procedure, og individuelle rettigheder er formgivet af den gregorianske kirkes kanoniske ret og dens konfrontation med kejserlig ret i investiturstriden. Magna Carta (1215) — kongens accept af at der er procedurer han ikke kan omgå — er det symbolske fundament for constitutional government. Det engelske parlament (fra 1265) og de franske États-généraux udviklede sig fra middelalderlige rådsrepræsentationsinstitutioner. Universitetet er den institutionelle kontinuitet der er mest synlig: Bologna (grundlagt 1088 som verdens ældste) har ubrudt virksomhed. Douglass North (Institutions, Institutional Change and Economic Performance, 1990) viser at institutionel path dependency er strukturelt: institutioner der engang er etablerede former efterfølgende muligheder på måder der er svære at bryde. Middelalderens institutionelle arv er ikke romantik men en empirisk observerbar strukturel realitet."}$$::jsonb,
  'mc','short',$${"concepts":["middelalderlige institutioner","universitetet","common law","Berman","Magna Carta","institutionel kontinuitet"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den medievale kirkes mest varige og ambivalente arv i moderne Europa — og hvad viser historiografiens nuancerede vurdering?","options":["Den medievale kirkes arv er genuint ambivalent: positiv (universiteter, hospitaler, systematisk fattigdomsomsorg, bevarelse af antik lærdom, kanonisk ret som model). Negativ (institutionaliseret antisemitisme, inkvisition og religiøs forfølgelse, kvinders strukturelle udelukkelse fra autoritet). Brian Tierney viser paradoksalt at middelalderlig kanonisk tradition producerede koncepter om individuel rettighed og konciliar begrænsning af autoritet — elementer der bidrog til liberale rettighedsteorier mod kirkens egne pretensioner","Den medievale kirkes arv er udelukkende positiv og alle negative aspekter er anakronistiske moraldomme der ikke respekterer periodens egne normer og forudsætninger","Den medievale kirkes arv er udelukkende negativ og enhver positiv vurdering er et ideologisk apologi for institutionel undertrykkelse og klerikalt magtmisbrug","Den medievale kirke har ingen varig institutionel arv i det moderne Europa da Reformationen og oplysningen fuldstændigt og endeligt brød med alle dens strukturer og traditioner"],"correct":"Den medievale kirkes arv er genuint ambivalent: positiv (universiteter, hospitaler, systematisk fattigdomsomsorg, bevarelse af antik lærdom, kanonisk ret som model). Negativ (institutionaliseret antisemitisme, inkvisition og religiøs forfølgelse, kvinders strukturelle udelukkelse fra autoritet). Brian Tierney viser paradoksalt at middelalderlig kanonisk tradition producerede koncepter om individuel rettighed og konciliar begrænsning af autoritet — elementer der bidrog til liberale rettighedsteorier mod kirkens egne pretensioner","accepted_answers":["Den medievale kirkes arv er genuint ambivalent: positiv (universiteter, hospitaler, systematisk fattigdomsomsorg, bevarelse af antik lærdom, kanonisk ret som model). Negativ (institutionaliseret antisemitisme, inkvisition og religiøs forfølgelse, kvinders strukturelle udelukkelse fra autoritet). Brian Tierney viser paradoksalt at middelalderlig kanonisk tradition producerede koncepter om individuel rettighed og konciliar begrænsning af autoritet — elementer der bidrog til liberale rettighedsteorier mod kirkens egne pretensioner"],"review_text":"Brian Tierney (The Idea of Natural Rights, 1997) fremsatte det overraskende argument at middelalderlig kanonisk ret — kirkens juridiske tradition — faktisk producerede tidlige versioner af individuelle rettigheder: kanonisterne debatterede om individer har rettigheder over for institutioner inklusive kirken selv. Konciliarisme (tesen om at et kirkekonvent er overordnet paven) er en middelalderlig idé der begrænser hierarkisk autoritet — et intellektuelt ressource for demokratisk tænkning. Den negative arv er ligeså reel: det fjerde Laterankoncil (1215) pålagde jøder at bære særlige mærker og forbød dem at bo i kristne kvarterer — en institutionel antisemitisme der lagde grunden for europæisk racisme. Inkvisitionen (fra 1184) og det regulerede kætteridrab var kirkelige institutioner. Karolien Spenner og Sara Ritchey (Medieval Women's Spirituality, 2015) viser at kirkens forhold til kvinder var mere komplekst end ren undertrykkelse: mystikere som Hildegard af Bingen, Birgitta af Sverige og Julian af Norwich formede europæisk spirituel kultur med en autoritet der oversteg mange mandlige gejstliges. Ambivalensen er historiografisk nødvendig: ensidig fordømmelse eller ensidig apologi er begge metodologisk utilstrækkelige."}$$::jsonb,
  'mc','short',$${"concepts":["middelalderkirke","Tierney","kanonisk ret","antisemitisme","kvinder og kirke","ambivalent arv"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det stærkeste argument for at middelalderen var en periode med reel innovation — og hvad er det stærkeste modargument?","options":["Innovation-argumentet: trevangsbrug og vandmøller øgede agrarproduktiviteten drastisk, gotisk arkitektur var en ingeniørmæssig bedrift, universiteter systematiserede vidensproduktion, kanonisk og common law rationaliserede retssystemer, arabisk viden i matematik og filosofi integrerede det europæiske intellektuelle system. Modargumentet: disse innovationer var spredte og langsomdiffunderende og Europa forblev teknologisk underlegent i forhold til Kina og den islamiske verden i størstedelen af perioden — de transformative spring kom med renæssancen og den videnskabelige revolution","Middelalderen producerede absolut nul innovation og alle fremskridt stammer enten fra antikken eller fra renæssancens brud med middelalderlig tradition","Middelalderen var teknologisk og intellektuelt overlegen over samtidige civilisationer i alle målbare dimensioner og begrebet stagnation er fuldstændig misvisende","Det er historisk umuligt at vurdere middelalderlig innovation da alle relevante primærkilder er gået tabt og vi er henvist til gætværk"],"correct":"Innovation-argumentet: trevangsbrug og vandmøller øgede agrarproduktiviteten drastisk, gotisk arkitektur var en ingeniørmæssig bedrift, universiteter systematiserede vidensproduktion, kanonisk og common law rationaliserede retssystemer, arabisk viden i matematik og filosofi integrerede det europæiske intellektuelle system. Modargumentet: disse innovationer var spredte og langsomdiffunderende og Europa forblev teknologisk underlegent i forhold til Kina og den islamiske verden i størstedelen af perioden — de transformative spring kom med renæssancen og den videnskabelige revolution","accepted_answers":["Innovation-argumentet: trevangsbrug og vandmøller øgede agrarproduktiviteten drastisk, gotisk arkitektur var en ingeniørmæssig bedrift, universiteter systematiserede vidensproduktion, kanonisk og common law rationaliserede retssystemer, arabisk viden i matematik og filosofi integrerede det europæiske intellektuelle system. Modargumentet: disse innovationer var spredte og langsomdiffunderende og Europa forblev teknologisk underlegent i forhold til Kina og den islamiske verden i størstedelen af perioden — de transformative spring kom med renæssancen og den videnskabelige revolution"],"review_text":"Frances Gies og Joseph Gies (Cathedral, Forge, and Waterwheel: Technology and Invention in the Middle Ages, 1994) dokumenterede systematisk middelalderlig teknologisk innovation: den tunge plov med jernplade der muliggjorde dyrkning af nordeuropæisk ler-jord, vindmøllens adoption, vandmøllens udbredelse til industrielle formål ud over maling (fulde-møller, jernhammere), det hesteskovens introduktion der fordobler trækdyrenes effektivitet. Arnold Paceys The Maze of Ingenuity (1974) viser at europæisk innovation i 1000-1400 var substantiel men ikke transformativ i den forstand at produktivitetsstigningerne var gradvise snarere end eksponentielle. Joseph Needham (Science and Civilisation in China) dokumenterede at Kina i 900-1300 var teknologisk overlegen på de fleste områder: papir, trykpresse, krudt, kompas var alle kinesiske opfindelser der nåede Europa via islamisk verden. Kenneth Pomereanz (The Great Divergence, 2000) viser at det store teknologiske spring kom i Europa ca. 1750-1850 — langt efter middelalderen. Det analytisk korrekte svar: middelalderens innovation var reel men dens transformative effekter var begrænsede og det store spring krævede yderligere forudsætninger."}$$::jsonb,
  'mc','short',$${"concepts":["middelalderlig innovation","Gies","Needham","Pomeranz","teknologisk diffusion","Great Divergence"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"middle_ages"}$$::jsonb,
  'mc_single',5,'auto',true,'middle_ages',9,5
);
